-- Integrity/indexes installed outside the JPA mappings on SQL Server.
CREATE UNIQUE INDEX uk_review_user_product_order ON reviews(user_id, product_id, order_id) WHERE order_id IS NOT NULL;
CREATE UNIQUE INDEX ux_store_creation_request ON stores(creation_request_key) WHERE creation_request_key IS NOT NULL;
CREATE UNIQUE INDEX ux_transaction_request ON transactions(request_key) WHERE request_key IS NOT NULL;
CREATE INDEX ix_order_payment_expiry ON orders(payment_status, status, payment_expires_at);
CREATE INDEX ix_jwt_session_user ON jwt_sessions(user_id);
CREATE INDEX ix_jwt_refresh_session ON jwt_refresh_tokens(session_id);
ALTER TABLE reviews ADD COLUMN image_public_id varchar(255);
-- SHIPPER is historical only; Java keeps these accounts disabled and grants no authority.
ALTER TABLE role_requests ADD CONSTRAINT ck_role_requests_canonical_role
    CHECK (target_role IN ('ADMIN','MANAGER','STAFF','USER','SHIPPER'));

